// Payload de Alertmanager. Aplica el umbral: si no se supera, devuelve [] y corta el flujo.
const body = ($input.first().json.body) || $input.first().json || {};
const alerts = Array.isArray(body.alerts) ? body.alerts : [];
const threshold = parseInt($env.ALERT_THRESHOLD || '3', 10);
const hasCritical = alerts.some(a => a.labels && a.labels.severity === 'critical');
const triggered = alerts.length >= threshold || hasCritical;
if (!triggered) {
  return [];
}
const first = alerts[0] || {};
const ann = body.commonAnnotations || first.annotations || {};
const labels = body.commonLabels || first.labels || {};
const summary = ann.summary || labels.alertname || 'Alerta sin resumen';
const description = ann.description || '';
const alertname = labels.alertname || (first.labels && first.labels.alertname) || 'unknown';
const severity = labels.severity || (first.labels && first.labels.severity) || 'warning';
return [{ json: {
  summary,
  description,
  alertname,
  severity,
  alertsCount: alerts.length,
  status: body.status || 'firing'
} }];

// Combina la alerta (nodo Prepare) con el contexto RAG para armar el prompt del modelo LLM.
const prep = $('Prepare').item.json;
const rag = $json || {};
const results = Array.isArray(rag.results) ? rag.results.slice(0, 3) : [];
const contextLines = results.map((r, i) =>
  `${i + 1}. [score ${Number(r.score).toFixed(3)} · ${r.clasificacion}] ${r.tipo_alerta}: ${r.resumen}
   Pasos: ${(r.pasos || []).join(' | ')}`
).join('
');
const system = 'Sos un analista de AIOps. Dado el contexto de una alerta y datos históricos de incidentes, sintetizá el problema en términos técnicos claros y proponé pasos de resolución accionables y numerados. Sé conciso. Respondé en español. Si el contexto histórico aplica, referencialo.';
const user = `Alerta: ${prep.alertname} (severidad: ${prep.severity})
Resumen: ${prep.summary}
Descripción: ${prep.description}
Alertas activas en el grupo: ${prep.alertsCount}

Contexto histórico (RAG, documentado=${rag.is_documented}):
${contextLines || 'Sin coincidencias relevantes.'}

Sintetizá el problema y proponé pasos de resolución.`;
return [{ json: { system, user, prep, is_documented: !!rag.is_documented } }];

// Selecciona proveedor LLM según LLM_PROVIDER (gemini | anthropic) y construye la request.
// Config de runtime del dashboard (nodo Get Config); si falló, fallback a env.
const cfg = $('Get Config').item.json || {};
const provider = (cfg.llm_provider || $env.LLM_PROVIDER || 'gemini').toLowerCase();
const { system, user } = $json;
let url, xApiKey, anthropicVersion, body;
if (provider === 'gemini') {
  const model = (provider === cfg.llm_provider && cfg.llm_model) || $env.GEMINI_MODEL || 'gemini-flash-latest';
  const key = $env.GEMINI_API_KEY || '';
  url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + key;
  xApiKey = '';
  anthropicVersion = '';
  body = {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { maxOutputTokens: 4096 } // gemini-flash-latest es thinking: los thoughts consumen este presupuesto
  };
} else {
  url = 'https://api.anthropic.com/v1/messages';
  const model = (provider === cfg.llm_provider && cfg.llm_model) || $env.CLAUDE_MODEL || 'claude-sonnet-4-6';
  xApiKey = $env.ANTHROPIC_API_KEY || '';
  anthropicVersion = '2023-06-01';
  body = {
    model,
    max_tokens: 1024,
    system,
    messages: [{ role: 'user', content: user }]
  };
}
return [{ json: { _provider: provider, _url: url, _x_api_key: xApiKey, _anthropic_version: anthropicVersion, _body: body } }];

// Extrae el texto según el proveedor: Gemini (candidates[]) o Anthropic (content[]).
const resp = $json || {};
let text;
if (Array.isArray(resp.candidates)) {
  text = (resp.candidates[0]?.content?.parts?.[0]?.text || '').trim() || 'Sin respuesta del modelo.';
} else if (Array.isArray(resp.content)) {
  const blocks = resp.content;
  text = blocks.filter(b => b.type === 'text').map(b => b.text).join('\n').trim() || 'Sin respuesta del modelo.';
} else {
  text = 'Sin respuesta del modelo.';
}
const bp = $('Build Prompt').item.json;
const prep = bp.prep;
const isNew = bp.is_documented === false;
const autoDoc = ($('Get Config').item.json || {}).auto_doc_enabled !== false;
const badgeText = autoDoc ? '🆕 Incidente nuevo — auto-documentado por Argos' : '🆕 Incidente nuevo — pendiente de documentar (auto-documentación desactivada)';
const badge = isNew ? `<p style="color:#b45309"><strong>${badgeText}</strong></p>` : '';
const html = `<h2>[ALERTA] ${prep.alertname} — ${prep.severity}</h2>` + badge +
  `<p><strong>Resumen:</strong> ${prep.summary}</p>` +
  `<pre style="white-space:pre-wrap;font-family:inherit">${text}</pre>` +
  `<hr><small>Generado por Argos (n8n + IA).</small>`;
return [{ json: { analysis: text, html, alertname: prep.alertname, severity: prep.severity, summary: prep.summary, is_documented: bp.is_documented } }];

// Auto-documentación desactivada en el dashboard: se registra el incidente NUEVO sin documento
// (estado 'nuevo') para documentarlo a mano desde el dashboard ('Generar documentación').
const prep = $('Build Prompt').item.json.prep;
const incident = {
  tipo_alerta: prep.alertname,
  resumen: prep.summary,
  pasos: [],
  severity: prep.severity,
  fuente: 'alertmanager',
  estado: 'nuevo',
  detected_at: new Date().toISOString()
};
return [{ json: { incident } }];

// Incidente NUEVO (sin match en la KB): arma el prompt para generar documentación técnica.
const prep = $('Build Prompt').item.json.prep;
const system = 'Sos un ingeniero SRE documentando un incidente NUEVO para la base de conocimiento de Argos. Generá documentación técnica concisa en Markdown con estas secciones exactas: "# Título", "## Descripción", "## Causa raíz probable", "## Pasos de resolución" (lista numerada), "## Prevención". Respondé en español y devolvé SOLO el Markdown, sin texto adicional.';
const user = `Alerta: ${prep.alertname} (severidad: ${prep.severity})
Resumen: ${prep.summary}
Descripción: ${prep.description}
Alertas activas en el grupo: ${prep.alertsCount}

Este incidente NO existe en la base de conocimiento de Argos. Generá su documentación técnica completa.`;
return [{ json: { system, user } }];

// Mismo ruteo dual-provider que 'Route LLM', reutilizado para la generación de documentación.
// Config de runtime del dashboard (nodo Get Config); si falló, fallback a env.
const cfg = $('Get Config').item.json || {};
const provider = (cfg.llm_provider || $env.LLM_PROVIDER || 'gemini').toLowerCase();
const { system, user } = $json;
let url, xApiKey, anthropicVersion, body;
if (provider === 'gemini') {
  const model = (provider === cfg.llm_provider && cfg.llm_model) || $env.GEMINI_MODEL || 'gemini-flash-latest';
  const key = $env.GEMINI_API_KEY || '';
  url = 'https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + key;
  xApiKey = '';
  anthropicVersion = '';
  body = {
    system_instruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { maxOutputTokens: 6144 } // incluye thinking tokens (con 1536 el doc salía truncado)
  };
} else {
  url = 'https://api.anthropic.com/v1/messages';
  const model = (provider === cfg.llm_provider && cfg.llm_model) || $env.CLAUDE_MODEL || 'claude-sonnet-4-6';
  xApiKey = $env.ANTHROPIC_API_KEY || '';
  anthropicVersion = '2023-06-01';
  body = {
    model,
    max_tokens: 1536,
    system,
    messages: [{ role: 'user', content: user }]
  };
}
return [{ json: { _provider: provider, _url: url, _x_api_key: xApiKey, _anthropic_version: anthropicVersion, _body: body } }];

// Extrae el Markdown generado y arma el payload de incidente para persistir en el RAG.
const resp = $json || {};
let text;
if (Array.isArray(resp.candidates)) {
  text = (resp.candidates[0]?.content?.parts?.[0]?.text || '').trim();
} else if (Array.isArray(resp.content)) {
  text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
} else {
  text = '';
}
const prep = $('Build Prompt').item.json.prep;
const incident = {
  tipo_alerta: prep.alertname,
  resumen: prep.summary,
  pasos: [],
  documento: text || 'Sin documentación generada.',
  severity: prep.severity,
  fuente: 'auto-generado',
  estado: 'auto_documentado',
  detected_at: new Date().toISOString()
};
return [{ json: { incident } }];

// Pool configurado en el dashboard (rag-api /notifications/recipients). Si viene vacío o la
// llamada falló (onError=continue), fallback a ALERT_RECIPIENT_EMAIL para no perder la alerta.
const list = Array.isArray($json.recipients) ? $json.recipients.filter(Boolean) : [];
const to = list.length ? list.join(', ') : ($env.ALERT_RECIPIENT_EMAIL || '');
if (!to) {
  throw new Error('Sin destinatarios configurados (pool vacío y ALERT_RECIPIENT_EMAIL sin definir)');
}
return [{ json: { to, recipients_source: list.length ? 'pool' : 'env', recipients_count: list.length || 1 } }];
